-- Тесты: вопросы + привязка к предмету (DDL)
ALTER TABLE "Test" ALTER COLUMN "groupId" DROP NOT NULL;
ALTER TABLE "Test" ADD COLUMN "subjectId" TEXT;
CREATE INDEX "Test_subjectId_idx" ON "Test"("subjectId");
ALTER TABLE "Test" ADD CONSTRAINT "Test_subjectId_fkey" FOREIGN KEY ("subjectId") REFERENCES "Subject"("id") ON DELETE SET NULL ON UPDATE CASCADE;

CREATE TABLE "TestQuestion" (
  "id" TEXT NOT NULL,
  "testId" TEXT NOT NULL,
  "order" INTEGER NOT NULL DEFAULT 0,
  "text" TEXT NOT NULL,
  "options" TEXT[],
  "correct" INTEGER NOT NULL DEFAULT 0,
  CONSTRAINT "TestQuestion_pkey" PRIMARY KEY ("id")
);
CREATE INDEX "TestQuestion_testId_idx" ON "TestQuestion"("testId");
ALTER TABLE "TestQuestion" ADD CONSTRAINT "TestQuestion_testId_fkey" FOREIGN KEY ("testId") REFERENCES "Test"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- Данные: предмет «Физика» (если ещё нет)
INSERT INTO "Subject"("id","name","price","color","active","createdAt")
SELECT 'seed_subj_fizika','Физика',0,'#0C8599',true,CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM "Subject" WHERE lower("name")='физика');

-- Тест «Механикалық қозғалыс»
INSERT INTO "Test"("id","title","subjectId","date","maxScore","createdBy","createdAt")
SELECT 'seed_test_mechmotion','«Механикалық қозғалыс» тесті',(SELECT "id" FROM "Subject" WHERE lower("name")='физика' ORDER BY "createdAt" ASC LIMIT 1),CURRENT_TIMESTAMP,20,'Импорт',CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM "Test" WHERE "id"='seed_test_mechmotion');

