  ('seed_q2','seed_test_mechmotion',2,'Қай жағдайда автобусты материалдық нүкте деп қарастыруға болады?',ARRAY['Автобустың салонының көлемін есептегенде','Дөңгелегінің диаметрін өлшегенде','Алматыдан Астанаға дейінгі қозғалыс уақытын анықтағанда','Есігінің ашылу механизмін зерттегенде','Автобустың боялатын бетінің ауданын есептегенде']::text[],2),
  ('seed_q3','seed_test_mechmotion',3,'Санақ жүйесінің толық құрамын таңдаңыз.',ARRAY['Тек санақ денесі','Санақ денесі және сағат','Координаталар жүйесі және траектория','Санақ денесі, координаталар жүйесі және уақыт өлшейтін құрал','Жол, орын ауыстыру және жылдамдық']::text[],3),
  ('seed_q4','seed_test_mechmotion',4,'Қозғалыс траекториясы дегеніміз не?',ARRAY['Қозғалған дене сызып өтетін сызық','Траекторияның толық ұзындығы','Бастапқы және соңғы нүктелерді қосатын бағытталған кесінді','Дененің бір секундта жүрген жолы','Дененің координаталар жүйесіндегі бастапқы орны']::text[],0),
  ('seed_q5','seed_test_mechmotion',5,'Жол мен орын ауыстыру туралы дұрыс тұжырымды табыңыз.',ARRAY['Екеуі де тек векторлық шамалар','Екеуі де тек скаляр шамалар','Жол векторлық, ал орын ауыстыру скаляр шама','Жол әрқашан орын ауыстыру модулінен кіші','Жол скаляр, ал орын ауыстыру векторлық шама']::text[],4),
  ('seed_q6','seed_test_mechmotion',6,'Жаяу жүргінші алдымен шығысқа қарай 300 м, содан кейін солтүстікке қарай 400 м жүрді. Оның жүрген жолы мен орын ауыстыру модулі қандай?',ARRAY['500 м және 700 м','700 м және 500 м','700 м және 700 м','100 м және 500 м','400 м және 300 м']::text[],1),
  ('seed_q7','seed_test_mechmotion',7,'Материалдық нүкте радиусы 20 м шеңбердің жартысын жүріп өтті. Оның жүрген жолы мен орын ауыстыру модулі қандай?',ARRAY['40π м және 0','20 м және 20π м','40 м және 20π м','20π м және 40 м','20π м және 20 м']::text[],3),
  ('seed_q8','seed_test_mechmotion',8,'Спортшы ұзындығы 1,2 км тұйық жолды бір рет толық айналып, бастапқы орнына келді. Жүрген жолы мен орын ауыстыру модулі:',ARRAY['1,2 км және 0','0 және 1,2 км','1,2 км және 1,2 км','0 және 0','2,4 км және 1,2 км']::text[],0),
  ('seed_q9','seed_test_mechmotion',9,'Бірқалыпты түзу сызықты қозғалысқа сәйкес келетін шартты таңдаңыз.',ARRAY['a=const≠0, v=0','a≠0, v бағыты үнемі өзгереді','a=0, v=const','a=0, v=0 ғана','a=const, v≠const']::text[],2),
